function photoReviewMarkersHtml(){const E=state.editor,d=E.photoDraft,diag=d?._diagnostics||{};if(!d||d.needsSetup||diag.engine!=='local'||!diag.width||!diag.height||!E.photoShowEnhanced)return'';const bars=(diag.reviewSystems||[]).map(sys=>{if(!photoSystemEnabled(d,+sys.index||0))return'';const ys=(sys.track||[]).flatMap(t=>t.lines||[]);if(!ys.length)return'';const y0=Math.max(0,(Math.min(...ys)-(+sys.gap||20)*.8)/diag.height*100),y1=Math.min(100,(Math.max(...ys)+(+sys.gap||20)*.8)/diag.height*100),xs=[...(sys.segments||[]).map(x=>+x.left||0),+((sys.segments||[]).slice(-1)[0]?.right||0)].filter(Boolean);return [...new Set(xs.map(x=>Math.round(x*10)/10))].map(x=>`<i class="photo-bar-marker" style="left:${(x/diag.width*100).toFixed(3)}%;top:${y0.toFixed(3)}%;height:${Math.max(.4,y1-y0).toFixed(3)}%"></i>`).join('')}).join('');const notes=(d.notes||[]).map((n,i)=>{if(!Number.isFinite(+n._x)||!Number.isFinite(+n._y))return'';const x=Math.max(0,Math.min(100,+n._x/diag.width*100)),y=Math.max(0,Math.min(100,+n._y/diag.height*100)),low=(+n.confidence||1)<.65?' low':'',mode=E.photoReviewMode==='remove'?' removable':'',off=Number.isFinite(+n._system)&&!photoSystemEnabled(d,+n._system)?' system-off':'',sel=(+E.photoDraftSelectedIndex===i)?' selected':'';return `<button class="photo-detect-marker${low}${mode}${off}${sel}" data-photo-note="${i}" style="left:${x.toFixed(3)}%;top:${y.toFixed(3)}%" title="Marker ${i+1} · ${h(NOTE.midiName(n.midi,d.key||state.song.key))} · ${h(durationName(n.duration))}${Number.isFinite(+n._system)?` · system ${+n._system+1}`:''}"><span>${i+1}</span></button>`}).join('');return bars+notes}
function sortPhotoDraft(){const d=state.editor.photoDraft;if(!d?.notes)return;d.notes.sort((a,b)=>(+a.bar||1)-(+b.bar||1)||(+a.beat||1)-(+b.beat||1)||(+a._x||0)-(+b._x||0))}
function togglePhotoSystem(si){const E=state.editor,d=E.photoDraft,count=Math.max(+d?.staffSystems||0,d?._diagnostics?.reviewSystems?.length||0);if(!d||si<0||si>=count)return;if(!Array.isArray(d._systemEnabled))d._systemEnabled=Array.from({length:count},()=>true);const enabled=d._systemEnabled.filter(v=>v!==false).length;if(d._systemEnabled[si]!==false&&enabled<=1){toast('Keep at least one staff system selected.','warn');return}d._systemEnabled[si]=d._systemEnabled[si]===false;if(d._systemEnabled[si]===false&&d.notes?.[E.photoDraftSelectedIndex]&&(+d.notes[E.photoDraftSelectedIndex]._system||0)===si)E.photoDraftSelectedIndex=-1;const selected=photoSelectedNotes(d).length;E.photoStatus=`Staff-system selection updated: ${selected} notes will be imported.`;renderEditor()}
