  $('#soundEngine').onchange=async e=>{m.soundEngine=e.target.value;applyAudioPrefs();saveMidiPrefs();AUDIO.panic();if(m.soundEngine==='studio'){try{setMidiStatus('Loading warm samples...');await AUDIO.unlock();await AUDIO.prepare(monitorInstrument());setMidiStatus('Studio Warm ready')}catch(err){toast(err.message,'danger')}}else setMidiStatus('Light Synth ready')};
  $('#soundWarmth').oninput=e=>{m.warmth=+e.target.value;AUDIO.setWarmth(m.warmth);$('#warmthValue').textContent=Math.round(m.warmth*100)+'%';saveMidiPrefs()};
  $('#soundRoom').oninput=e=>{m.room=+e.target.value;AUDIO.setRoom(m.room);$('#roomValue').textContent=Math.round(m.room*100)+'%';saveMidiPrefs()};
