  $('#midiVolume').oninput=e=>{m.volume=+e.target.value;AUDIO.setVolume(m.volume);$('#midiVolValue').textContent=Math.round(m.volume*100)+'%';saveMidiPrefs()};
  $('#midiExpression').oninput=e=>{m.expression=+e.target.value;AUDIO.setExpression(m.expression);$('#expressionValue').textContent=Math.round(m.expression*100)+'%';saveMidiPrefs()};
