  $('#cursorBeat').onchange=e=>state.beatCursor.beat=Math.max(1,Math.min(4,+e.target.value||1));
  $('#startRecord').onclick=startMidiRecord;$('#stopRecord').onclick=stopMidiRecord;$('#playTake').onclick=playMidiTake;$('#clearTake').onclick=()=>{if(m.take.length&&!confirm('Clear the current take?'))return;m.take=[];updateMidiIndicators()};$('#addTake').onclick=()=>commitMidiTake(false);$('#replaceTake').onclick=()=>commitMidiTake(true);$('#exportTakeMidi').onclick=exportMidiTake;$('#exportTakeWav').onclick=exportMidiTakeWav;$('#toEditor').onclick=()=>show('editor');
  renderKeyboard();renderControllerMap();refreshMidiPorts(MIDI.ports());applyAudioPrefs();updateMidiIndicators();
