function renderControllerMap(){const host=$('#controllerMap');if(!host)return;const m=state.midi,targets=[['modulation','Modulation / vibrato'],['volume','Master volume'],['expression','Expression'],['warmth','Warmth'],['brightness','Brightness / tone'],['room','Room / reverb'],['attack','Attack'],['release','Release'],['sustain','Sustain pedal'],['play','Transport: Play'],['stop','Transport: Stop'],['record','Transport: Record']];host.innerHTML='';targets.forEach(([key,label])=>{const cc=Object.entries(m.controlMap).find(([,v])=>v===key)?.[0]??'';const row=document.createElement('div');row.className='controller-row';row.innerHTML=`<span>${h(T(label))}</span><label>CC <input type="number" min="0" max="127" value="${h(cc)}" placeholder="--"></label><button class="btn small learn ${m.learnTarget===key?'primary':''}">${h(T(m.learnTarget===key?'Move control…':'Learn'))}</button><button class="btn small clear">${h(T('Clear'))}</button>`;const input=row.querySelector('input');input.onchange=()=>{Object.keys(m.controlMap).forEach(k=>{if(m.controlMap[k]===key)delete m.controlMap[k]});if(input.value!=='')m.controlMap[String(Math.max(0,Math.min(127,+input.value||0)))]=key;saveMidiPrefs();renderControllerMap()};row.querySelector('.learn').onclick=()=>{m.learnTarget=m.learnTarget===key?'':key;if($('#midiLearnState'))$('#midiLearnState').textContent=m.learnTarget?'Move a knob / slider on the keyboard…':'Ready';renderControllerMap()};row.querySelector('.clear').onclick=()=>{Object.keys(m.controlMap).forEach(k=>{if(m.controlMap[k]===key)delete m.controlMap[k]});if(m.learnTarget===key)m.learnTarget='';saveMidiPrefs();renderControllerMap()};host.appendChild(row)})}
function uiRange(id,value,labelId,text){const e=$('#'+id);if(e)e.value=value;if(labelId&&$('#'+labelId))$('#'+labelId).textContent=text}
function applyMappedControl(target,value){const m=state.midi,v=Math.max(0,Math.min(127,+value||0)),x=v/127;m.controlValues[target]=v;if(target==='volume'){m.volume=x;AUDIO.setVolume(x);uiRange('midiVolume',x,'midiVolValue',Math.round(x*100)+'%');uiRange('editorMaster',x,'editorMasterValue',Math.round(x*100)+'%')}else if(target==='expression'){m.expression=x;AUDIO.setExpression(x);uiRange('midiExpression',x,'expressionValue',Math.round(x*100)+'%')}else if(target==='warmth'){m.warmth=x;AUDIO.setWarmth(x);uiRange('soundWarmth',x,'warmthValue',Math.round(x*100)+'%');uiRange('editorWarm',x,'editorWarmValue',Math.round(x*100)+'%')}else if(target==='brightness'){m.brightness=x;AUDIO.setBrightness(x);uiRange('midiBrightness',x,'brightnessValue',Math.round(x*100)+'%')}else if(target==='room'){m.room=x*.6;AUDIO.setRoom(m.room);uiRange('soundRoom',m.room,'roomValue',Math.round(m.room*100)+'%');uiRange('editorRoom',m.room,'editorRoomValue',Math.round(m.room*100)+'%')}else if(target==='attack'){m.attack=x;AUDIO.setAttack(x);uiRange('midiAttack',x,'attackValue',Math.round(x*100)+'%')}else if(target==='release'){m.release=x;AUDIO.setRelease(x);uiRange('midiRelease',x,'releaseValue',Math.round(x*100)+'%')}else if(target==='modulation'){m.modulation=x;AUDIO.setModulation(x);uiRange('midiModulation',x,'modulationValue',Math.round(x*100)+'%')}else if(target==='sustain'){m.sustain=v>=64;AUDIO.setSustain(m.sustain);updateMidiIndicators()}else if(v>=64&&target==='play')playSong(true);else if(v>=64&&target==='stop')stopAudio();else if(v>=64&&target==='record'){if(m.recording||m.armed)stopMidiRecord();else startMidiRecord()}saveMidiPrefs()}
function handleProgramChange(program){const m=state.midi;if(!m.programChange)return;program=+program||0;let inst='Piano';if(program===71)inst='Clarinet Bb';else if(program===65)inst='Alto Sax Eb';else if(program===66)inst='Tenor Sax Bb';else if(program===21)inst='Accordion';else if(program>=24&&program<=31)inst='Guitar';else if(program>=40&&program<=47)inst='Violin';else if(program>=64&&program<=67)inst=program===66?'Tenor Sax Bb':'Alto Sax Eb';m.monitorInstrument=inst;saveMidiPrefs();const sel=$('#monitorInstrument');if(sel)sel.value=inst;setMidiStatus('Loaded '+(NOTE.INSTRUMENTS[inst]?.label||inst)+' from Program '+program);if(m.soundEngine==='studio')AUDIO.prepare(inst).catch(()=>{})}
function handleMidiEvent(e){if(!e||!channelAllowed(e))return;const m=state.midi;if(e.type==='cc'){if($('#meterCc'))$('#meterCc').textContent='CC'+e.controller+' = '+e.value;if(e.controller===1&&$('#meterMod'))$('#meterMod').textContent=e.value;if(e.controller===11&&$('#meterExpression'))$('#meterExpression').textContent=e.value;if(e.controller===64&&$('#meterSustain'))$('#meterSustain').textContent=e.value;if(m.learnTarget){Object.keys(m.controlMap).forEach(k=>{if(m.controlMap[k]===m.learnTarget)delete m.controlMap[k]});m.controlMap[String(e.controller)]=m.learnTarget;const learned=m.learnTarget;m.learnTarget='';saveMidiPrefs();if($('#midiLearnState'))$('#midiLearnState').textContent='Mapped CC'+e.controller+' → '+learned;if(state.view==='midi')renderControllerMap()}const target=m.controlMap[String(e.controller)];if(target)applyMappedControl(target,e.value);if(m.thru&&m.outputId)MIDI.sendEvent(e);return}if(e.type==='program'){handleProgramChange(e.program);if(m.thru&&e.data)MIDI.sendRaw(e.data);return}if(e.type==='aftertouch'){m.modulation=Math.max(0,Math.min(1,(+e.pressure||0)/127));AUDIO.setModulation(m.modulation);if(m.thru&&e.data)MIDI.sendRaw(e.data);return}midiEvent(e);if(e.type==='noteon'||e.type==='noteoff')editorMidiWriteEvent(e)}
function midiEvent(e){const m=state.midi;if(!channelAllowed(e))return;if(e.type==='cc'&&e.controller===64){m.sustain=e.value>=64;AUDIO.setSustain(m.sustain);if(m.thru)MIDI.sendEvent(e);updateMidiIndicators();return}if(e.type==='pitchbend'){m.pitchBend=e.normalized||0;AUDIO.setPitchBend(m.pitchBend*200);if(m.thru)MIDI.sendEvent(e);return}if(e.type!=='noteon'&&e.type!=='noteoff'){if(m.thru&&e.data)MIDI.sendRaw(e.data);return}const note=playedMidi(e.note),vel=velocityValue(e.velocity);const key=document.querySelector(`.key[data-midi="${note}"]`);if(key)key.classList.toggle('active',e.type==='noteon');if($('#lastMidi'))$('#lastMidi').textContent=(e.type==='noteon'?'Note ':'Off ')+note+' - '+NOTE.midiName(note)+' - vel '+vel;const editorAudition=state.view==='editor';if(m.monitor||editorAudition){applyAudioPrefs();if(e.type==='noteon')AUDIO.noteOn(note,vel,monitorInstrument());else AUDIO.noteOff(note)}if(m.thru&&m.outputId)MIDI.sendEvent({...e,note,velocity:vel});if(!m.recording)return;if(m.recordMode==='step'){if(e.type==='noteon')recordStepNote(note,vel);return}const k=(e.channel||1)+':'+note;if(e.type==='noteon')m.pending.set(k,{note,velocity:vel,startMs:performance.now()});else finalizeLiveNote(k,performance.now())}
function quantizeBeat(v,duration=false){const q=state.midi.quantize;if(!q)return Math.max(duration ? .0625 : 0,+v.toFixed(3));return duration?Math.max(q,Math.round(v/q)*q):Math.max(0,Math.round(v/q)*q)}
function writtenMidi(input,p){return Math.max(0,Math.min(127,Math.round(input-(state.recordAsWritten?(NOTE.INSTRUMENTS[p.instrument]?.soundingOffset||0):0))))}
function makeTakeNote(input,startAbs,dur,velocity){const p=state.song.parts[state.partIndex],bpb=NOTE.beatsPerBar(state.song),bar=Math.floor(startAbs/bpb)+1,beat=(startAbs%bpb)+1,midi=writtenMidi(input,p),staff=resolveGrandInputStaff(p,midi);return{bar,beat:+beat.toFixed(3),duration:+Math.max(.0625,dur).toFixed(3),midi,staff,velocity:velocity||88,lyric:'',_inputMidi:input}}
function recordStepNote(note,vel){const m=state.midi,dur=+($('#recordDur')?.value||1),abs=(state.beatCursor.bar-1)*4+(state.beatCursor.beat-1);m.take.push(makeTakeNote(note,abs,dur,vel));advanceCursor(dur);if($('#cursorBar'))$('#cursorBar').value=state.beatCursor.bar;if($('#cursorBeat'))$('#cursorBeat').value=state.beatCursor.beat;updateMidiIndicators()}
function finalizeLiveNote(key,now){const m=state.midi,x=m.pending.get(key);if(!x)return;m.pending.delete(key);const msBeat=60000/(+state.song.bpm||92),rawStart=Math.max(0,(x.startMs-m.recordStartMs)/msBeat),rawDur=Math.max(.03,(now-x.startMs)/msBeat),start=m.recordBaseBeat+quantizeBeat(rawStart),dur=quantizeBeat(rawDur,true);m.take.push(makeTakeNote(x.note,start,dur,x.velocity));updateMidiIndicators()}
function stopMidiTimers(){const m=state.midi;m.countTimers.forEach(clearTimeout);m.countTimers=[];if(m.metroTimer){clearInterval(m.metroTimer);m.metroTimer=null}}
async function startMidiRecord(){const m=state.midi;if(m.recording||m.armed)return;try{applyAudioPrefs();await AUDIO.unlock();if(m.soundEngine==='studio')await AUDIO.prepare(monitorInstrument())}catch(e){toast(e.message,'danger');return}if(m.take.length&&!confirm('Start a new take and clear the current take?'))return;m.take=[];m.pending.clear();state.song.bpm=Math.max(20,Math.min(300,+($('#midiBpm')?.value||state.song.bpm||92)));m.recordBaseBeat=(state.beatCursor.bar-1)*NOTE.beatsPerBar(state.song)+(state.beatCursor.beat-1);if(m.recordMode==='step'){m.recording=true;setRecordState('Step recording - play keys');updateMidiIndicators();return}m.armed=true;const msBeat=60000/state.song.bpm,total=Math.max(0,m.countIn)*4;setRecordState(total?'Count-in...':'Recording');if(total){for(let i=0;i<total;i++){m.countTimers.push(setTimeout(()=>{AUDIO.click(i%4===0);setRecordState('Count-in '+(total-i));},i*msBeat))}m.countTimers.push(setTimeout(()=>beginLiveRecord(),total*msBeat))}else beginLiveRecord();updateMidiIndicators()}
