async function commitMidiTake(replace){const t=state.midi.take;if(!t.length){toast('Record a take first.','warn');return}const p=state.song.parts[state.partIndex];if(replace&&!confirm('Replace all notes in "'+p.name+'" with this take?'))return;p.notes=replace?t.map(({_inputMidi,...n})=>n):[...(p.notes||[]),...t.map(({_inputMidi,...n})=>n)];p.notes.sort((a,b)=>(a.bar-b.bar)||(a.beat-b.beat));await saveSong()}
function safeFile(s){return String(s||'music63').replace(/[^\p{L}\p{N}_-]+/gu,'_')}
function exportMidiTake(){const t=normalizedTake();if(!t.length){toast('Record a take first.','warn');return}const p=state.song.parts[state.partIndex],part={...p,name:(p.name||p.instrument)+' take',notes:t.map(({startBeat,_inputMidi,...n})=>n)},song={...state.song,parts:[part]};MIDI.downloadMidi(song,part,safeFile(state.song.title)+'-'+safeFile(p.name||p.instrument)+'-take.mid');toast('MIDI take exported.','ok')}
