function updateMidiIndicators(){const m=state.midi;if($('#takeCount'))$('#takeCount').textContent=m.take.length+' '+T('notes in current take');if($('#sustainState'))$('#sustainState').textContent=T(m.sustain?'Sustain ON':'Sustain off');if($('#startRecord')){$('#startRecord').disabled=m.recording||m.armed;$('#startRecord').textContent=T(m.armed?'Count-in...':m.recording?'Recording...':'Record')}if($('#stopRecord'))$('#stopRecord').disabled=!m.recording&&!m.armed;if($('#playTake'))$('#playTake').disabled=!m.take.length;if($('#clearTake'))$('#clearTake').disabled=!m.take.length;if($('#addTake'))$('#addTake').disabled=!m.take.length;if($('#replaceTake'))$('#replaceTake').disabled=!m.take.length;if($('#exportTakeMidi'))$('#exportTakeMidi').disabled=!m.take.length;if($('#exportTakeWav'))$('#exportTakeWav').disabled=!m.take.length;setTimeout(localize,0)}
function synthPreset(inst){return {Piano:['triangle',.05,.55],Accordion:['sawtooth',.03,.8],Guitar:['triangle',.01,.4],Violin:['sawtooth',.08,.8],'Clarinet Bb':['square',.04,.65],'Clarinet Bb (as written)':['square',.04,.65],'Alto Sax Eb':['sawtooth',.04,.7],'Tenor Sax Bb':['sawtooth',.04,.72]}[inst]||['sine',.03,.6]}
