async function importMidi(e){const f=e.target.files[0];if(!f)return;try{const r=MIDI.parse(await f.arrayBuffer()),s=defaultSong();s.title=f.name.replace(/\.(mid|midi)$/i,'');s.bpm=r.bpm;s.parts=r.parts.map((p,i)=>({...p,id:uid('part'),name:p.name||'Track '+(i+1),instrument:'Piano'}));state.song=s;state.partIndex=0;show('editor');toast('MIDI imported. Review instrument assignments.')}catch(err){toast(err.message,'danger')}}
