function audioTargetOptionsHtml(){const E=state.editor,cur=state.song?.parts?.[state.partIndex];return [['current','Current part: '+(cur?.name||'Part')],['Clarinet Bb','Clarinet B♭ - one melody line'],['Piano','Piano right hand - one melody line'],['Accordion','Accordion - one melody line'],['Alto Sax Eb','Alto Sax E♭ - one melody line'],['Tenor Sax Bb','Tenor Sax B♭ - one melody line']].map(([v,l])=>`<option value="${h(v)}" ${E.audioTargetInstrument===v?'selected':''}>${h(l)}</option>`).join('')}
