  const bpb=NOTE.beatsPerBar(s),name='Backing - '+inst;let part=s.parts.find(p=>p.name===name&&p.instrument===inst);if(!part){part={id:uid('part'),name,instrument:inst,notes:[]};s.parts.push(part)}
  const notes=[];chs.forEach((c,i)=>{const next=chs[i+1],abs=((+c.bar||1)-1)*bpb+((+c.beat||1)-1),nextAbs=next?((+next.bar||1)-1)*bpb+((+next.beat||1)-1):abs+Math.max(1,bpb-((+c.beat||1)-1)),span=Math.max(.5,nextAbs-abs);let pitches=chordToPitches(c.symbol,inst==='Accordion'?'accordion':'piano');if(inst==='Guitar')pitches=pitches.map(x=>x+12);for(let off=0;off<span-.01;off+=1){const total=abs+off,bar=Math.floor(total/bpb)+1,beat=(total%bpb)+1,root=pitches[0]||48;notes.push({bar,beat,duration:.5,midi:root,velocity:76,lyric:'',rest:false});pitches.slice(1).forEach((m,j)=>notes.push({bar,beat:Math.min(bpb,beat+.5),duration:.5,midi:m,velocity:58+j*3,lyric:'',rest:false}))}});part.notes=notes;state.partIndex=s.parts.indexOf(part);state.song.scoreBars=Math.max(+s.scoreBars||8,...notes.map(n=>+n.bar||1));toast('Backing part rebuilt from detected chords.','ok');return part
